def initialize_invoice_states(apps, schema_editor):
    invoice = apps.get_model("invoices", "Invoice")
    term = apps.get_model("invoices", "Term")
    alias = schema_editor.connection.alias
    invoice.objects.using(alias).filter(is_posted=True).update(status="posted")
    for row in invoice.objects.using(alias).filter(date__isnull=False).iterator():
        years = list(
            term.objects.using(alias)
            .filter(start_date__lte=row.date, end_date__gte=row.date)
            .values_list("pk", flat=True)[:2]
        )
        if len(years) == 1:
            invoice.objects.using(alias).filter(pk=row.pk).update(
                fiscal_year_id=years[0]
            )


